// HasGroup applies the HasEdge predicate on the "group" edge.
func HasGroup() predicate.OtohaCatalogImageModel {
	return predicate.OtohaCatalogImageModel(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, GroupTable, GroupColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasGroupWith applies the HasEdge predicate on the "group" edge with a given conditions (other predicates).
func HasGroupWith(preds ...predicate.Group) predicate.OtohaCatalogImageModel {
	return predicate.OtohaCatalogImageModel(func(s *sql.Selector) {
		step := newGroupStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.OtohaCatalogImageModel) predicate.OtohaCatalogImageModel {
	return predicate.OtohaCatalogImageModel(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.OtohaCatalogImageModel) predicate.OtohaCatalogImageModel {
	return predicate.OtohaCatalogImageModel(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.OtohaCatalogImageModel) predicate.OtohaCatalogImageModel {
	return predicate.OtohaCatalogImageModel(sql.NotPredicates(p))
}
